"""Frozen catalog output generated by workbench templates."""
from soliplex_a2ui_workbench.workbench_templates import (
    chart_record,
    form_record,
    python_record,
)


def test_form_template_uses_fixed_intake_catalog_registration():
    assert form_record("activity_form", "surface_form", "Intake") == {"activityMessageId":"activity_form","surfaceId":"surface_form","catalogId":"urn:soliplex:catalog:workbench:1","component":"PlaceForm","template":"intake","title":"Intake"}
def test_chart_compiles_to_graphics_two_chart_spec():
    assert chart_record("activity_chart", "surface_chart", "Counts", "bar", [{"id":"north","label":"North","value":80}]) == {"activityMessageId":"activity_chart","surfaceId":"surface_chart","catalogId":"urn:soliplex:catalog:graphics:2","component":"Chart","selection":[],"description":"Counts","spec":{"kind":"bar","title":"Counts","points":[{"id":"north","label":"North","value":80}]}}
def test_python_repl_record_is_declarative_and_inert():
    assert python_record("activity_python", "surface_python", "Demo", "print(1)") == {"activityMessageId":"activity_python","surfaceId":"surface_python","catalogId":"urn:soliplex:catalog:lab:1","component":"PythonRepl","title":"Demo","source":"print(1)","output":""}
